import { api, post } from './client';
import { InboxView, LibraryView, VersionAnnotation } from './Library';
import BackupView from './BackupView';
import OfflineView from './OfflineView';
import CompareView from './CompareView';
import TimelineView, { DiagnosticsPanel, ObservationList, QualitySummary, useObservations, type ArchiveVersion, type Observation, type HistorySummary, type Diagnostic } from './TimelineView';
import ArchiveReview from './ArchiveReview';
import LandingLifecycle from './LandingLifecycle';
import RuleEditor, { type MonitoringRule } from './RuleEditor';
import { useCallback, useEffect, useRef, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import { ArrowDownToLine, ArrowLeft, ArrowRight, ArrowUpRight, Check, ChevronRight, Clock3, ExternalLink, FileText, FolderArchive, Globe2, History, LayoutDashboard, Link2, LoaderCircle, LockKeyhole, LogOut, Menu, MessageSquare, Monitor, Pause, Play, Plus, RefreshCw, Search, Settings2, ShieldCheck, Sparkles, Trash2, X } from 'lucide-react';

type Site = { id: string; name: string; url: string; kind: 'own' | 'competitor'; intervalHours: number; discoveryIntervalHours: number; nextDiscoveryAt?: string; lastDiscoveryAt?: string; includePaths: string[]; excludePaths: string[]; maxPages: number; includeSubdomains: boolean; paused: boolean; pageCount: number; versionCount: number; lastCheckedAt?: string; nextCheckAt?: string; ignoreSelectors: string[]; notes?: string };
type Page = { source: string; firstSeenAt?: string; lastSuccessfulAt?: string; lifecycle: 'new' | 'changed' | 'missing' | 'recovered'; sitemapState: string; sitemapSeenAt?: string; ignoreRules: MonitoringRule[]; importantRules: MonitoringRule[]; id: string; url: string; title: string; lastCheckedAt?: string; lastStatus?: string; versionCount: number; latestVersionId?: string; latestCheckId?: string; lastChangeAt?: string; referenceVersionId?: string | null; pendingConfirmation?: { count: number; retries: number; firstSeenAt: string } | null };
type Version = ArchiveVersion;
type Event = { id: string; kind: string; url: string; siteName: string; createdAt: string; message: string };
type Job = { id: string; siteId: string; pageId?: string; kind: string; status: string; manual: number; paused: number; attempts: number; error?: string; url: string; siteName: string; createdAt: string; startedAt?: string; availableAt: string };
type Dashboard = { version: string; stats: { sites: number; pages: number; versions: number; bytes: number; queued: number; running: number }; events: Event[]; storage: { freeBytes: number; totalBytes: number; minFreeBytes: number }; worker: { available: boolean; message?: string; schedulerEnabled: boolean; version?: string; expectedVersion?: string; compatible?: boolean }; diagnosticsStatus?: { bytes: number; maxBytes: number; retentionHours: number; count: number }; queue: Job[] };
type SiteDetail = { site: Site; pages: Page[]; events: Event[]; jobs: Job[] };
type PageDetail = { page: Page; site: Site; jobs: Job[]; versions: Version[]; checks: Observation[]; notes: string; referenceVersionId?: string | null; historySummary?: HistorySummary; diagnostics?: Diagnostic[] };
type Route = { view: 'overview' | 'sites' | 'site' | 'page' | 'inbox' | 'library' | 'backup'; id?: string; versionId?: string };
type AuthStatus = { setupRequired: boolean; authenticated: boolean };

const date = (value?: string, short = false) => value ? new Intl.DateTimeFormat('it-IT', { day: '2-digit', month: 'short', ...(short ? {} : { year: 'numeric' }), hour: '2-digit', minute: '2-digit' }).format(new Date(value)) : '—';
const bytes = (value?: number) => { if (value === undefined || value === null || !Number.isFinite(value)) return '—'; if (!value) return '0 B'; const unit = Math.min(Math.floor(Math.log(value) / Math.log(1024)), 4); return `${new Intl.NumberFormat('it-IT', { maximumFractionDigits: unit > 1 ? 1 : 0 }).format(value / 1024 ** unit)} ${['B', 'KB', 'MB', 'GB', 'TB'][unit]}`; };
const host = (url: string) => { try { return new URL(url).hostname.replace(/^www\./, ''); } catch { return url; } };
const urlPath = (url: string) => { try { const parsed = new URL(url); return parsed.pathname + parsed.search; } catch { return url; } };
const routeFromHash = (): Route => { const [view, id, versionId] = window.location.hash.replace(/^#\/?/, '').split('/'); return ['sites', 'site', 'page', 'inbox', 'library', 'backup'].includes(view) ? { view: view as Route['view'], id, versionId } : { view: 'overview' }; };
const go = (view: Route['view'], id?: string) => { window.location.hash = `/${view}${id ? `/${id}` : ''}`; };
const statusLabel = (status?: string) => ({ archive_reset: 'Scansione pulita', observed: 'Evidenza conservata', partial: 'Copia da verificare', baseline: 'Regole aggiornate', quality_restored: 'Copia completata', sitemap_absent: 'Fuori dalla sitemap', sitemap_returned: 'Rientrata nella sitemap', ok: 'Archiviata', unavailable: 'Da verificare', recovered: 'Tornata online', changed: 'Modificata', new: 'Prima copia', captured: 'Archiviata', unchanged: 'Invariata', error: 'Errore', failed: 'Errore', missing: 'Non raggiungibile', disappeared: 'Non raggiungibile', removed: 'Non raggiungibile', restored: 'Tornata online', returned: 'Versione ritornata', cancelled: 'Interrotto', queued: 'In attesa', running: 'In corso', succeeded: 'Completato', success: 'Completato', blocked: 'Accesso bloccato', discovered: 'Pagina scoperta', discovery: 'Ricerca pagine', capture: 'Acquisizione' }[status || ''] || (status ? 'Controllata' : 'Da acquisire'));
const isErrorStatus = (status?: string) => !!status && ['partial', 'error', 'failed', 'unavailable', 'missing', 'disappeared', 'removed', 'blocked'].includes(status);

function Spinner({ label = 'Caricamento' }: { label?: string }) { return <div className="loading" role="status"><LoaderCircle className="spin" size={22} /><span>{label}…</span></div>; }
type Action = (fn: () => Promise<unknown>, message: string) => Promise<void>;

function ScanButton({ siteId, pageId, running, perform, compact = false }: { siteId: string; pageId?: string; running: boolean; perform: Action; compact?: boolean }) {
  const [busy, setBusy] = useState(false);
  return <button className={`button ${compact ? 'secondary compact' : 'primary'}`} disabled={busy} onClick={async () => {
    setBusy(true);
    try { await perform(() => post(pageId ? `/api/pages/${pageId}/scan` : `/api/sites/${siteId}/scan`, { force: true, discover: !pageId }), 'Controllo manuale prioritario richiesto. Lo stato si aggiorna qui sotto.'); }
    finally { setBusy(false); }
  }} title={running ? 'Interrompe il tentativo corrente e avvia un nuovo controllo.' : 'Scarica di nuovo la pagina anche se il monitoraggio è in pausa. Conserva una nuova versione quando rileva modifiche.'}>
    {busy ? <LoaderCircle className="spin" size={17} /> : <RefreshCw size={17} />}{busy ? 'Richiesta in corso…' : running ? 'Riavvia controllo' : compact ? 'Scarica ora' : 'Controlla e scarica ora'}
  </button>;
}

function AcquisitionStatus({ jobs, paused, error }: { jobs: Job[]; paused: boolean; error?: string }) {
  const running = jobs.find(job => job.status === 'running');
  const queued = jobs.filter(job => job.status === 'queued');
  const next = queued.find(job => !job.paused || job.manual);
  const seconds = running?.startedAt ? Math.max(0, Math.floor((Date.now() - Date.parse(running.startedAt)) / 1000)) : 0;
  return <section className="acquisition-status" aria-label="Stato acquisizioni" aria-live="polite">
    <div><strong>{running ? `${statusLabel(running.kind)} in corso · ${seconds} secondi` : next ? Date.parse(next.availableAt) > Date.now() ? `Nuovo tentativo previsto: ${date(next.availableAt, true)}` : 'Controllo pronto, in attesa del motore' : paused ? 'Monitoraggio automatico in pausa' : 'Nessuna acquisizione in corso'}</strong>
      {running && <p>{urlPath(running.url)} · tentativo {running.attempts}/3. Il tempo massimo per un lavoro è 3 minuti.</p>}
      {!!queued.length && <p>{queued.length}{queued.length >= 100 ? '+' : ''} {queued.length === 1 ? 'controllo in attesa' : 'controlli in attesa'}. I controlli manuali hanno la precedenza.</p>}
      <p>{paused ? 'Il comando manuale funziona anche in pausa e non riattiva la pianificazione.' : '«Controlla e scarica ora» avvia una nuova visita. Se il contenuto è invariato, viene registrato il controllo senza duplicare la versione.'}{running && ' «Riavvia controllo» interrompe il tentativo corrente.'}</p>
    </div>
    {(next?.error || error) && <div className="acquisition-error"><strong>Ultimo errore registrato</strong><p>{next?.error || error}</p></div>}
  </section>;
}

function DeleteSiteModal({ site, close, deleted }: { site: Site; close: () => void; deleted: (pendingFiles: number) => Promise<void> }) {
  const [confirmed, setConfirmed] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  return <Modal title="Elimina sito dall’archivio" subtitle={site.name} close={() => { if (!busy) close(); }}>
    <form onSubmit={async event => {
      event.preventDefault(); if (!confirmed || busy) return; setBusy(true); setError('');
      try {
        const result = await api<{ pendingFiles: number }>(`/api/sites/${site.id}`, { method: 'DELETE', body: JSON.stringify({ confirmSiteId: site.id }) });
        await deleted(result.pendingFiles);
      } catch (error) { setError((error as Error).message); } finally { setBusy(false); }
    }}><div className="modal-body">
      <p>Verranno eliminati <strong>{site.pageCount} {site.pageCount === 1 ? 'pagina' : 'pagine'}</strong>, <strong>{site.versionCount} {site.versionCount === 1 ? 'versione' : 'versioni'}</strong>, note e cronologia di questo sito. I controlli in corso e quelli programmati saranno annullati.</p>
      <p>I file usati anche da altri siti verranno conservati. Questa operazione non può essere annullata dall’app; per recuperare le copie serve un backup precedente.</p>
      <a className="text-button" href="/api/export" download><ArrowDownToLine size={16} /> Scarica prima un backup dell’archivio</a>
      <label className="checkbox-label"><input type="checkbox" checked={confirmed} onChange={event => setConfirmed(event.target.checked)} disabled={busy} /><span>Confermo l’eliminazione del sito e delle sue copie archiviate.</span></label>
      {error && <div className="notice error" role="alert">{error}</div>}
    </div><div className="modal-footer"><button type="button" className="button secondary" disabled={busy} onClick={close}>Annulla</button><button className="button danger" disabled={!confirmed || busy}>{busy ? <LoaderCircle className="spin" size={17} /> : <Trash2 size={17} />}{busy ? 'Eliminazione…' : 'Elimina definitivamente'}</button></div></form>
  </Modal>;
}
function ResetSiteModal({ site, close, done }: { site: Site; close: () => void; done: (message: string) => Promise<void> }) {
  type Preview = { token: string; versions: number; pages: number; annotatedVersions: number; reclaimableBytes: number };
  const [preview, setPreview] = useState<Preview>(); const [confirmed, setConfirmed] = useState(false);
  const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function load() {
    setPreview(undefined); setConfirmed(false); setError(''); setBusy(true);
    try { setPreview(await api<Preview>(`/api/sites/${site.id}/reset`)); }
    catch (cause) { setError((cause as Error).message); } finally { setBusy(false); }
  }
  useEffect(() => { void load(); }, [site.id]);
  return <Modal title="Azzera copie e riscarica" subtitle={site.name} close={() => { if (!busy) close(); }}>
    <form onSubmit={async event => {
      event.preventDefault(); if (!preview || !confirmed || busy) return; setBusy(true); setError('');
      try {
        const result = await post<{ message: string; pendingFiles: number }>(`/api/sites/${site.id}/reset`, { token: preview.token, confirmSiteId: site.id });
        await done(result.message + (result.pendingFiles ? ' Alcuni file non condivisi non sono stati rimossi dal disco: controlla i permessi del volume dati.' : ''));
      } catch (cause) { setConfirmed(false); setError((cause as Error).message); } finally { setBusy(false); }
    }}><div className="modal-body">
      {!preview && !error && <p role="status">Preparazione dell’anteprima…</p>}
      {preview && <><p>Verranno eliminate <strong>tutte le {preview.versions} copie</strong> di questo sito, inclusi screenshot e HTML, preferiti, tag e appunti sulle singole copie{preview.annotatedVersions ? ` (${preview.annotatedVersions} copie annotate o preferite)` : ''}.</p>
        <p>Rimangono il sito, i {preview.pages} indirizzi, le impostazioni e le note delle pagine. La nuova scansione partirà da zero, senza confrontarsi con le vecchie copie. Le date dei controlli rimangono registrate con l’indicazione dei file rimossi.</p>
        <p>Spazio recuperabile: <strong>{bytes(preview.reclaimableBytes)}</strong>. I file usati da altri siti rimangono disponibili. Per recuperare le copie eliminate serve un backup precedente; se il sito oggi non è raggiungibile, la nuova scansione non potrà ricrearle.</p>
        <a className="text-button" href="/api/export" download><ArrowDownToLine size={16} /> Scarica prima un backup dell’archivio</a>
        <label className="checkbox-label"><input type="checkbox" disabled={busy} checked={confirmed} onChange={event => setConfirmed(event.target.checked)} /><span>Confermo l’eliminazione di tutte le copie di {site.name} e l’avvio di una scansione pulita.</span></label>
      </>}
      {error && <div className="notice error" role="alert">{error}</div>}
    </div><div className="modal-footer"><button type="button" className="button secondary" disabled={busy} onClick={close}>Annulla</button>{error && <button type="button" className="button secondary" disabled={busy} onClick={load}>Aggiorna anteprima</button>}<button className="button danger" disabled={busy || !preview || !confirmed}>{busy ? <LoaderCircle className="spin" size={17} /> : <RefreshCw size={17} />}Conferma azzeramento e scansione</button></div></form>
  </Modal>;
}
function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'green' | 'amber' }) { return <span className={`badge ${tone}`}>{children}</span>; }
function Empty({ icon, title, children, action }: { icon: ReactNode; title: string; children: ReactNode; action?: ReactNode }) { return <div className="empty"><div className="empty-icon">{icon}</div><h3>{title}</h3><p>{children}</p>{action}</div>; }

export default function App() {
  const [auth, setAuth] = useState<AuthStatus | null>(null);
  const [initialError, setInitialError] = useState('');
  useEffect(() => {
    const load = () => api<AuthStatus>('/api/auth/status').then(setAuth).catch(error => setInitialError(error.message));
    load(); window.addEventListener('session-expired', load); return () => window.removeEventListener('session-expired', load);
  }, []);
  if (!auth) return <main className="startup"><Brand />{initialError ? <div className="notice error">{initialError}<button className="text-button" onClick={() => window.location.reload()}>Riprova</button></div> : <Spinner label="Apertura dell’archivio" />}</main>;
  if (!auth.authenticated) return <AuthScreen setup={auth.setupRequired} onSuccess={() => setAuth({ setupRequired: false, authenticated: true })} />;
  return <Workspace onLogout={async () => { await post('/api/auth/logout'); setAuth({ setupRequired: false, authenticated: false }); }} />;
}

function Brand() { return <div className="brand"><div className="brand-icon"><History size={24} strokeWidth={1.8} /></div><div><strong>Landing Archive</strong><span>La memoria dei tuoi siti</span></div></div>; }

function AuthScreen({ setup, onSuccess }: { setup: boolean; onSuccess: () => void }) {
  const [username, setUsername] = useState(''); const [password, setPassword] = useState(''); const [confirm, setConfirm] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function submit(event: FormEvent) { event.preventDefault(); if (setup && password !== confirm) { setError('Le due password non coincidono.'); return; } setBusy(true); setError(''); try { await post(setup ? '/api/auth/setup' : '/api/auth/login', { username, password }); onSuccess(); } catch (error) { setError((error as Error).message); } finally { setBusy(false); } }
  return <main className="auth-layout"><section className="auth-story"><Brand /><div><span className="eyebrow light">IL TUO OSSERVATORIO WEB</span><h1>Le pagine cambiano.<br />La loro storia resta.</h1><p>Conserva le landing, ritrova le offerte passate e osserva come si evolvono i siti che segui.</p><div className="auth-steps"><span><Globe2 size={18} /> Segui i siti</span><span><FolderArchive size={18} /> Conserva le versioni</span><span><History size={18} /> Esplora la storia</span></div></div><span className="auth-local"><ShieldCheck size={17} /> Il tuo archivio rimane sul tuo dispositivo.</span></section><section className="auth-form-wrap"><form className="auth-form" onSubmit={submit}><div className="auth-lock"><LockKeyhole size={23} /></div><span className="eyebrow">{setup ? 'BENVENUTO NEL TUO ARCHIVIO' : 'IL TUO SPAZIO PRIVATO'}</span><h2>{setup ? 'Prepariamo il tuo accesso.' : 'Bentornato.'}</h2><p>{setup ? 'Crea un account locale per proteggere siti, catture e annotazioni.' : 'Accedi per consultare la storia dei siti che segui.'}</p><label>Nome utente<input autoFocus autoComplete="username" required minLength={3} maxLength={40} value={username} onChange={event => setUsername(event.target.value)} /></label><label>Password<input type="password" autoComplete={setup ? 'new-password' : 'current-password'} required minLength={setup ? 12 : undefined} value={password} onChange={event => setPassword(event.target.value)} />{setup && <small>Almeno 12 caratteri. Conservala in un posto sicuro.</small>}</label>{setup && <label>Ripeti la password<input type="password" autoComplete="new-password" required value={confirm} onChange={event => setConfirm(event.target.value)} /></label>}{error && <div className="notice error" role="alert">{error}</div>}<button className="button primary full" disabled={busy}>{busy ? <LoaderCircle size={18} className="spin" /> : <ArrowRight size={18} />}{setup ? 'Crea il tuo archivio' : 'Accedi'}</button></form></section></main>;
}

function Workspace({ onLogout }: { onLogout: () => Promise<void> }) {
  const [route, setRoute] = useState<Route>(routeFromHash); const [sites, setSites] = useState<Site[]>([]); const [dashboard, setDashboard] = useState<Dashboard | null>(null); const [detail, setDetail] = useState<SiteDetail | PageDetail | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [toast, setToast] = useState(''); const [editingSite, setEditingSite] = useState<Site | 'new' | null>(null); const [deletingSite, setDeletingSite] = useState<Site | null>(null); const [mobileNav, setMobileNav] = useState(false); const [search, setSearch] = useState(''); const [results, setResults] = useState<{ id: string; url: string; title: string; siteName: string }[] | null>(null);
  const requestId = useRef(0); const currentRoute = useRef(route); currentRoute.current = route;
  const load = useCallback(async (silent = false) => {
    const id = ++requestId.current;
    if (!silent) setLoading(true);
    try {
      const [siteData, dashboardData, detailData] = await Promise.all([api<{ sites: Site[] }>('/api/sites'), api<Dashboard>('/api/dashboard'), route.id && (route.view === 'site' || route.view === 'page') ? api<SiteDetail | PageDetail>(`/api/${route.view === 'site' ? 'sites' : 'pages'}/${route.id}`) : Promise.resolve(null)]);
      if (id !== requestId.current) return;
      setSites(siteData.sites); setDashboard(dashboardData); setDetail(detailData); setError('');
    } catch (error) { if (id === requestId.current) setError((error as Error).message); }
    finally { if (id === requestId.current) setLoading(false); }
  }, [route.view, route.id, route.versionId]);
  useEffect(() => { const handler = () => { setRoute(routeFromHash()); setDetail(null); setMobileNav(false); setSearch(''); window.scrollTo(0, 0); }; window.addEventListener('hashchange', handler); return () => window.removeEventListener('hashchange', handler); }, []);
  useEffect(() => { load(); }, [load]);
  const activeJobs = (dashboard?.stats.queued || 0) + (dashboard?.stats.running || 0);
  useEffect(() => { const timer = window.setInterval(() => { if (!document.hidden) load(true); }, activeJobs ? 4000 : 30000); return () => clearInterval(timer); }, [load, activeJobs]);
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(''), 5500); return () => clearTimeout(timer); }, [toast]);
  useEffect(() => { if (!search.trim()) { setResults(null); return; } let cancelled = false; const timer = window.setTimeout(() => { api<{ pages: NonNullable<typeof results> }>(`/api/search?q=${encodeURIComponent(search.trim())}`).then(data => { if (!cancelled) setResults(data.pages); }).catch(() => { if (!cancelled) setResults([]); }); }, 250); return () => { cancelled = true; clearTimeout(timer); }; }, [search]);
  const notify = (message: string) => setToast(message);
  const perform = async (fn: () => Promise<unknown>, message: string) => { try { await fn(); notify(message); await load(true); } catch (error) { setError((error as Error).message); } };
  const selectedSite = detail?.site || null;
  const deleted = async (pendingFiles: number) => {
    ++requestId.current; setDeletingSite(null); setDetail(null); setError(''); setSearch(''); setResults(null);
    notify(pendingFiles ? 'Sito eliminato. Alcuni file non sono stati rimossi dal disco: controlla i permessi del volume dati.' : 'Sito e archivio eliminati. I file condivisi con altri siti sono conservati.');
    if (currentRoute.current.view === 'sites') await load(true); else go('sites');
  };
  return <div className="app-shell"><aside className={`sidebar ${mobileNav ? 'open' : ''}`}><a className="brand-link" href="#/overview"><Brand /></a><div className="sidebar-label">IL TUO ARCHIVIO</div><nav aria-label="Navigazione principale"><a href="#/overview" className={`nav-item ${route.view === 'overview' ? 'active' : ''}`}><LayoutDashboard size={19} /> Panoramica</a><a href="#/sites" className={`nav-item ${['sites','site','page'].includes(route.view) ? 'active' : ''}`}><Globe2 size={19} /> Siti monitorati <span>{sites.length}</span></a><a href="#/inbox" className={`nav-item ${route.view === 'inbox' ? 'active' : ''}`}><Sparkles size={19} /> Novità da leggere</a><a href="#/library" className={`nav-item ${route.view === 'library' ? 'active' : ''}`}><MessageSquare size={19} /> Raccolta</a></nav><div className="sidebar-label sites-label">SITI RECENTI <button className="icon-button" aria-label="Aggiungi sito" onClick={() => setEditingSite('new')}><Plus size={17} /></button></div><div className="sidebar-sites">{sites.slice(0, 8).map(site => <a key={site.id} href={`#/site/${site.id}`} className={`sidebar-site ${selectedSite?.id === site.id ? 'selected' : ''}`}><span className={`site-dot ${site.paused ? 'paused' : ''}`} /><span>{site.name}</span>{site.kind === 'own' && <span className="own-dot" title="Un tuo sito" />}</a>)}{!sites.length && <p className="sidebar-hint">I siti che aggiungi compariranno qui.</p>}</div><div className="sidebar-bottom"><div className="local-status"><ShieldCheck size={19} /><div><strong>Archivio locale</strong><span>I tuoi dati, sul tuo dispositivo</span></div></div><a className="nav-item subdued" href="#/backup"><FolderArchive size={18} /> Backup e ripristino</a><button className="nav-item subdued" onClick={() => perform(onLogout, '')}><LogOut size={18} /> Esci</button><div className="sidebar-version">LANDING ARCHIVE <span>v{dashboard?.version || "…"}</span></div></div></aside>{mobileNav && <button className="nav-scrim" aria-label="Chiudi navigazione" onClick={() => setMobileNav(false)} />}
    <div className="workspace"><header className="topbar"><button className="icon-button mobile-toggle" aria-label="Apri navigazione" onClick={() => setMobileNav(!mobileNav)}><Menu size={23} /></button><div className="breadcrumb"><span>Archivio</span><ChevronRight size={14} /><strong>{route.view === 'overview' ? 'Panoramica' : route.view === 'sites' ? 'Siti monitorati' : route.view === 'inbox' ? 'Novità da leggere' : route.view === 'library' ? 'Raccolta' : route.view === 'backup' ? 'Backup e ripristino' : selectedSite?.name || 'Dettaglio'}</strong></div><div className="global-search"><Search size={17} /><input aria-label="Cerca pagine nell’archivio" placeholder="Cerca nell’archivio…" value={search} onChange={event => setSearch(event.target.value)} />{search && <button className="icon-button" aria-label="Cancella ricerca" onClick={() => setSearch('')}><X size={15} /></button>}{results !== null && <div className="search-results">{results.length ? results.map(result => <button key={result.id} onClick={() => { go('page', result.id); setSearch(''); }}><span>{result.title || urlPath(result.url)}</span><small>{result.siteName} · {host(result.url)}</small></button>) : <p>Nessuna pagina trovata.</p>}</div>}</div><div className={`worker-status ${dashboard?.worker.available ? '' : 'offline'}`}><span />{dashboard?.worker.available ? dashboard?.stats.running ? 'Acquisizioni in corso' : activeJobs ? 'Controlli in attesa' : sites.some(site => !site.paused) ? 'Monitoraggio attivo' : 'Archivio pronto' : 'Acquisizioni non disponibili'}</div></header>
    <main className="main-content">{error && <div className="notice error" role="alert"><span>{error}</span><button className="text-button" onClick={() => load()}>Riprova</button><button className="icon-button" aria-label="Chiudi errore" onClick={() => setError('')}><X size={17} /></button></div>}{dashboard && !dashboard.worker.available && <div className="notice amber"><Clock3 size={18} /><span>{dashboard.worker.message || "Il servizio di acquisizione non è attivo. Controlla lo stato dell’app in Umbrel."}</span></div>}{dashboard && !dashboard.worker.schedulerEnabled && <div className="notice amber">I controlli automatici sono disattivati. Puoi usare «Controlla e scarica ora» per una visita manuale.</div>}{dashboard && dashboard.storage.freeBytes < dashboard.storage.minFreeBytes && <div className="notice amber"><FolderArchive size={18} /><span>Lo spazio libero è sotto la soglia di sicurezza. Le nuove acquisizioni sono sospese; le versioni esistenti restano disponibili.</span></div>}
    {loading ? <Spinner label="Caricamento dell’archivio" /> : route.view === 'overview' && dashboard ? <Overview data={dashboard} sites={sites} addSite={() => setEditingSite('new')} /> : route.view === 'inbox' ? <InboxView sites={sites} /> : route.view === 'library' ? <LibraryView sites={sites} /> : route.view === 'backup' ? <BackupView restored={() => load(true)} /> : route.view === 'sites' ? <SitesView sites={sites} addSite={() => setEditingSite('new')} remove={setDeletingSite} perform={perform} jobs={dashboard?.queue || []} /> : route.view === 'site' && detail && !('page' in detail) ? <SiteView detail={detail} edit={() => setEditingSite(detail.site)} remove={() => setDeletingSite(detail.site)} perform={perform} refresh={() => load(true)} notify={notify} /> : route.view === 'page' && detail && 'page' in detail ? <PageView detail={detail} versionId={route.versionId} perform={perform} refresh={() => load(true)} /> : <Empty icon={<Globe2 size={30} />} title="Pagina non disponibile" action={<a className="button secondary" href="#/overview">Torna alla panoramica</a>}>Il contenuto richiesto non è disponibile nell’archivio.</Empty>}
    </main><footer className="workspace-footer"><span><LockKeyhole size={13} /> Le catture restano nel tuo archivio locale</span><a href="/api/source" download>Codice sorgente · AGPL-3.0</a></footer></div>
    {deletingSite && <DeleteSiteModal site={deletingSite} close={() => setDeletingSite(null)} deleted={deleted} />}{editingSite && <SiteModal site={editingSite === 'new' ? undefined : editingSite} close={() => setEditingSite(null)} saved={async () => { setEditingSite(null); notify(editingSite === 'new' ? 'Sito aggiunto. La prima acquisizione è in coda.' : 'Impostazioni del sito salvate.'); await load(true); }} />}{toast && <div className="toast" role="status"><Check size={18} /><span>{toast}</span><button className="icon-button" aria-label="Chiudi notifica" onClick={() => setToast('')}><X size={16} /></button></div>}
  </div>;
}

function Overview({ data, sites, addSite }: { data: Dashboard; sites: Site[]; addSite: () => void }) {
  return <><div className="page-heading"><div><span className="eyebrow">OGNI CAMBIAMENTO, AL SUO POSTO</span><h1>Il web cambia. Tu tieni il filo.</h1><p>La storia dei tuoi siti e dei competitor, raccolta giorno dopo giorno.</p></div><button className="button primary" onClick={addSite}><Plus size={18} /> Aggiungi sito</button></div><div className="stats-grid">{([{ label: 'Siti monitorati', value: data.stats.sites, icon: <Globe2 size={20} />, sub: `${sites.filter(site => site.kind === 'own').length} tuoi · ${sites.filter(site => site.kind === 'competitor').length} competitor` }, { label: 'Pagine scoperte', value: data.stats.pages, icon: <FileText size={20} />, sub: 'Landing e pagine nell’archivio' }, { label: 'Versioni conservate', value: data.stats.versions, icon: <History size={20} />, sub: 'Copie salvate nel tempo' }, { label: 'Spazio archivio', value: bytes(data.stats.bytes), icon: <FolderArchive size={20} />, sub: `${bytes(data.storage.freeBytes)} liberi sul disco` }]).map(stat => <div className="stat-card" key={stat.label}><div><span>{stat.label}</span>{stat.icon}</div><strong>{stat.value}</strong><small>{stat.sub}</small></div>)}</div>
    {!sites.length ? <section className="welcome-panel"><div className="welcome-illustration"><div className="illustration-page back"><span /><span /><span /></div><div className="illustration-page front"><div /><span /><span /><span /><History size={34} /></div></div><div><span className="eyebrow">LA PRIMA PAGINA DELLA TUA STORIA</span><h2>Da quale sito cominciamo?</h2><p>Aggiungi un dominio o una landing. Conserveremo una prima copia e controlleremo i cambiamenti alla frequenza che scegli.</p><button className="button primary" onClick={addSite}><Plus size={18} /> Aggiungi il primo sito</button></div></section> : <div className="overview-columns"><section className="panel"><div className="panel-heading"><div><h2>I siti che segui</h2><p>Un punto di partenza per ogni storia.</p></div><a className="text-button" href="#/sites">Vedi tutti <ArrowRight size={16} /></a></div><div className="site-list">{sites.slice(0, 5).map(site => <SiteRow key={site.id} site={site} />)}</div></section><section className="panel activity-panel"><div className="panel-heading"><div><h2>Ultimi movimenti</h2><p>Nuove pagine, versioni e controlli.</p></div><span className="small-icon"><History size={19} /></span></div><EventList events={data.events.slice(0, 8)} /></section></div>}
    <section className="panel acquisition-health" aria-label="Stato del motore e dello spazio temporaneo"><div><h2>Motore di acquisizione</h2><p>App {data.version} · Motore {data.worker.version || 'versione non disponibile'}</p>{data.worker.compatible === false ? <p className="engine-mismatch" role="status">App e motore non sono compatibili. Aggiorna il motore in Umbrel alla versione {data.worker.expectedVersion || data.version}; le copie già salvate restano disponibili.</p> : <p>{data.worker.available ? 'Motore disponibile per le acquisizioni.' : data.worker.message || 'Motore temporaneamente non disponibile.'}</p>}</div>{data.diagnosticsStatus && <div><h2>Campioni temporanei</h2><p><strong>{bytes(data.diagnosticsStatus.bytes)}</strong> su {bytes(data.diagnosticsStatus.maxBytes)} · {data.diagnosticsStatus.count} campioni</p><p>I campioni ordinari scadono entro {data.diagnosticsStatus.retentionHours} ore. Le evidenze nuove restano nell’archivio.</p>{data.diagnosticsStatus.bytes >= data.diagnosticsStatus.maxBytes && <p className="engine-mismatch">Spazio temporaneo esaurito: ulteriori campioni delle anomalie possono non essere conservati.</p>}</div>}</section>
    {!!data.queue.length && <section className="panel queue-panel"><div className="panel-heading"><div><h2>Acquisizioni in coda</h2><p>{data.stats.running} in corso · {data.stats.queued} in attesa</p></div><LoaderCircle size={19} className={data.stats.running ? 'spin' : ''} /></div><div className="queue-list">{data.queue.slice(0, 8).map(job => <div key={job.id}><span className={`queue-dot ${job.status === 'running' ? 'running' : ''}`} /><div><strong>{job.siteName || host(job.url)}</strong><small title={job.url}>{job.url}</small></div><span className="muted job-kind">{statusLabel(job.kind)}</span><Badge tone={job.status === 'running' ? 'green' : 'neutral'}>{statusLabel(job.status)}</Badge></div>)}</div></section>}
    <section className="insight-strip"><div className="insight-icon"><Sparkles size={21} /></div><p><strong>Una landing può sparire. La tua copia rimane.</strong><span>Aggiungi anche gli indirizzi trovati negli annunci e nelle newsletter: le pagine senza collegamenti pubblici possono sfuggire alla scansione.</span></p></section></>;
}

function SiteRow({ site }: { site: Site }) { return <a className="site-row" href={`#/site/${site.id}`}><div className={`site-avatar ${site.kind === 'own' ? 'own' : ''}`}>{site.name.slice(0, 1).toUpperCase()}</div><div className="site-row-name"><strong>{site.name}</strong><span>{host(site.url)}</span></div><div className="site-row-count"><strong>{site.pageCount || 0} pagine</strong><span>{site.versionCount || 0} versioni</span></div><Badge tone={site.paused ? 'neutral' : 'green'}>{site.paused ? 'In pausa' : `Ogni ${site.intervalHours} h`}</Badge><ChevronRight size={17} className="muted" /></a>; }

function EventList({ events }: { events: Event[] }) { return events.length ? <div className="event-list">{events.map(event => <div className="event-row" key={event.id}><div className={`event-marker ${isErrorStatus(event.kind) ? 'warning' : ''}`}>{isErrorStatus(event.kind) ? <Clock3 size={14} /> : event.kind === 'discovered' || event.kind === 'new' ? <Plus size={14} /> : <History size={14} />}</div><div><div className="event-top"><strong>{event.siteName || host(event.url)}</strong><time>{date(event.createdAt, true)}</time></div><p>{event.message || statusLabel(event.kind)}</p>{event.url && <small title={event.url}>{urlPath(event.url)}</small>}</div></div>)}</div> : <div className="activity-empty"><Clock3 size={26} /><p>La storia comincia con il primo controllo.</p><span>Qui compariranno i movimenti dei tuoi siti.</span></div>; }

function SitesView({ sites, addSite, remove, perform, jobs }: { sites: Site[]; addSite: () => void; remove: (site: Site) => void; perform: Action; jobs: Job[] }) {
  const [filter, setFilter] = useState('all'); const [query, setQuery] = useState(''); const filtered = sites.filter(site => (filter === 'all' || site.kind === filter) && `${site.name} ${site.url}`.toLowerCase().includes(query.toLowerCase()));
  return <><div className="page-heading"><div><span className="eyebrow">IL TUO OSSERVATORIO</span><h1>Siti monitorati</h1><p>Segui i tuoi progetti e osserva come si muovono i competitor.</p></div><button className="button primary" onClick={addSite}><Plus size={18} /> Aggiungi sito</button></div><div className="list-toolbar"><div className="tabs">{[{ key: 'all', label: 'Tutti i siti' }, { key: 'own', label: 'I miei siti' }, { key: 'competitor', label: 'Competitor' }].map(tab => <button key={tab.key} className={filter === tab.key ? 'selected' : ''} onClick={() => setFilter(tab.key)}>{tab.label} <span>{sites.filter(site => tab.key === 'all' || site.kind === tab.key).length}</span></button>)}</div><div className="input-search"><Search size={16} /><input aria-label="Filtra siti" placeholder="Filtra per nome o dominio" value={query} onChange={event => setQuery(event.target.value)} /></div></div>{filtered.length ? <div className="site-cards">{filtered.map(site => <article className="site-card" key={site.id}><a className="site-card-link" href={`#/site/${site.id}`}><div className="site-card-top"><div className={`site-avatar ${site.kind === 'own' ? 'own' : ''}`}>{site.name.slice(0, 1).toUpperCase()}</div><Badge>{site.kind === 'own' ? 'Il mio sito' : 'Competitor'}</Badge><ArrowUpRight size={19} /></div><h2>{site.name}</h2><p className="domain">{host(site.url)}</p><div className="site-card-numbers"><div><strong>{site.pageCount || 0}</strong><span>Pagine</span></div><div><strong>{site.versionCount || 0}</strong><span>Versioni</span></div></div><div className="site-card-footer"><span><span className={`site-dot ${site.paused ? 'paused' : ''}`} />{site.paused ? 'Monitoraggio in pausa' : `Controllo ogni ${site.intervalHours} h`}</span><small>Ultimo: {date(site.lastCheckedAt, true)}</small></div></a><div className="site-card-actions"><ScanButton siteId={site.id} running={jobs.some(job => job.siteId === site.id && job.status === "running")} perform={perform} compact /><button className="button danger-outline compact" onClick={() => remove(site)} aria-label={`Elimina ${site.name}`}><Trash2 size={15} /> Elimina</button></div></article>)}</div> : <div className="panel"><Empty icon={<Globe2 size={30} />} title={sites.length ? 'Nessun sito corrispondente' : 'Il tuo archivio parte da un indirizzo'} action={!sites.length && <button className="button primary" onClick={addSite}><Plus size={17} /> Aggiungi sito</button>}>{sites.length ? 'Prova a cambiare filtro o ricerca.' : 'Aggiungi il primo sito per iniziare a conservarne la storia.'}</Empty></div>}</>;
}

function SiteView({ detail, edit, remove, perform, refresh, notify }: { detail: SiteDetail; edit: () => void; remove: () => void; perform: (fn: () => Promise<unknown>, message: string) => Promise<void>; refresh: () => Promise<void>; notify: (message: string) => void }) {
  const { site, pages } = detail; const [addingPage, setAddingPage] = useState(false); const [resetting, setResetting] = useState(false);
  return <><a className="back-link" href="#/sites"><ArrowLeft size={15} /> Tutti i siti</a><div className="page-heading site-heading"><div><div className="heading-badges"><Badge tone="green">{site.kind === 'own' ? 'Il mio sito' : 'Competitor'}</Badge>{site.paused && <Badge>In pausa</Badge>}</div><h1>{site.name}</h1><a className="external-link" href={site.url} target="_blank" rel="noreferrer">{site.url}<ExternalLink size={13} /></a></div><div className="button-group"><a className="button secondary" href={`/api/sites/${site.id}/export`} download><ArrowDownToLine size={17} /> Esporta sito offline</a><button className="button secondary" onClick={edit}><Settings2 size={17} /> Impostazioni</button><ScanButton siteId={site.id} running={detail.jobs.some(job => job.status === "running")} perform={perform} /><button className="button danger-outline" onClick={() => setResetting(true)}><RefreshCw size={17} /> Azzera copie e riscarica</button><button className="button danger-outline" onClick={remove}><Trash2 size={17} /> Elimina sito</button></div></div><div className="site-summary"><span><FileText size={17} /><strong>{pages.length}</strong> pagine</span><span><History size={17} /><strong>{site.versionCount || 0}</strong> versioni</span><span><Clock3 size={17} /> Ogni {site.intervalHours} ore</span><span className="next-check">{site.paused ? 'Pianificazione sospesa' : `Prossimo controllo: ${date(site.nextCheckAt, true)}`}</span></div><AcquisitionStatus jobs={detail.jobs} paused={site.paused} error={detail.events.find(event => isErrorStatus(event.kind))?.message} /><div className="discovery-summary"><strong>Ricerca nuove landing ogni {site.discoveryIntervalHours} ore</strong><span>Ultima ricerca: {date(site.lastDiscoveryAt, true)}</span><span>{site.paused ? 'Ricerca automatica in pausa' : `Prossima ricerca: ${date(site.nextDiscoveryAt, true)}`}</span><small>Il controllo manuale del sito include anche la ricerca di nuovi indirizzi.</small></div><LandingLifecycle pages={pages} maxPages={site.maxPages} date={date} statusLabel={statusLabel} add={() => setAddingPage(true)} /><div className="site-lower-grid"><section className="panel"><div className="panel-heading"><div><h2>Attività del sito</h2><p>La cronologia dei controlli e delle scoperte.</p></div></div><EventList events={detail.events.slice(0, 8)} /></section><section className="panel site-guidance"><Link2 size={24} /><h2>Hai trovato una nuova landing?</h2><p>Gli indirizzi presenti solo in annunci, email o aree riservate possono sfuggire alla ricerca automatica. Aggiungili qui per seguirne la storia.</p><button className="button secondary" onClick={() => setAddingPage(true)}><Plus size={16} /> Aggiungi un indirizzo</button><div className="site-guidance-note"><ShieldCheck size={17} /><span>Le versioni precedenti rimangono disponibili anche quando una pagina cambia o scompare.</span></div></section></div>{resetting && <ResetSiteModal site={site} close={() => setResetting(false)} done={async message => { setResetting(false); notify(message); await refresh(); }} />}{addingPage && <AddPageModal site={site} close={() => setAddingPage(false)} saved={async () => { setAddingPage(false); notify('Pagina aggiunta. La prima acquisizione è in coda.'); await refresh(); }} />}</>;
}

function PageView({ detail, perform, refresh, versionId }: { versionId?: string; detail: PageDetail; refresh: () => Promise<void>; perform: (fn: () => Promise<unknown>, message: string) => Promise<void> }) {
  const { page, site } = detail;
  const versions = [...detail.versions].sort((a, b) => b.capturedAt.localeCompare(a.capturedAt) || b.id.localeCompare(a.id));
  const defaultId = page.latestVersionId || detail.referenceVersionId || page.referenceVersionId || versions[0]?.id || '';
  const [view, setView] = useState<'offline' | 'screenshot'>('offline');
  const [selectedId, setSelectedId] = useState(versionId || defaultId);
  const [selectedObservation, setSelectedObservation] = useState<Observation>();
  const [explicitSelection, setExplicitSelection] = useState(false);
  const [mode, setMode] = useState<'preview' | 'compare' | 'checks' | 'rules'>('preview');
  const [notes, setNotes] = useState(detail.notes || '');
  const [savingNotes, setSavingNotes] = useState(false);
  const [imageError, setImageError] = useState(false);
  const observations = useObservations(page.id, detail.checks, detail.historySummary?.checks);
  useEffect(() => { setSelectedId(versionId || defaultId); setSelectedObservation(undefined); setExplicitSelection(false); setMode('preview'); setNotes(detail.notes || ''); }, [page.id, versionId]);
  useEffect(() => { if (!versions.some(version => version.id === selectedId) && versions.length) { setSelectedId(defaultId); setSelectedObservation(undefined); } }, [versions, selectedId, defaultId]);
  useEffect(() => setImageError(false), [selectedId]);
  const selected = versions.find(version => version.id === selectedId) || versions.find(version => version.id === defaultId) || versions[0];
  // A returned variant may reuse old files. Keep the accepted visit time for links in the offline page.
  const latestVisit = !versionId && !explicitSelection && selected?.id === page.latestVersionId ? observations.checks.find(check => check.versionId === selected.id && ['first', 'change', 'returned', 'baseline'].includes(check.evidence?.kind || '')) : undefined;
  const activeObservation = selectedObservation || latestVisit;
  function select(id: string, check?: Observation) { setSelectedId(id); setSelectedObservation(check); setExplicitSelection(true); setMode('preview'); }
  return <>
    <a className="back-link" href={`#/site/${site.id}`}><ArrowLeft size={15} /> {site.name}</a>
    <div className="page-heading detail-heading"><div><span className="eyebrow">STORIA DELLA PAGINA</span><h1>{page.title || urlPath(page.url)}</h1><a className="external-link" href={page.url} target="_blank" rel="noreferrer">{page.url}<ExternalLink size={13} /></a></div><ScanButton siteId={site.id} pageId={page.id} running={detail.jobs.some(job => job.status === 'running')} perform={perform} /></div>
    <AcquisitionStatus jobs={detail.jobs} paused={site.paused} error={detail.checks[0] && isErrorStatus(detail.checks[0].status) ? detail.checks[0].message : undefined} />
    {detail.historySummary && <div className="history-overview" aria-label="Riepilogo dello storico"><span><strong>{detail.historySummary.confirmed}</strong> confermate</span><span><strong>{detail.historySummary.observed}</strong> evidenze da verificare</span><span><strong>{detail.historySummary.legacy}</strong> copie precedenti</span><span><strong>{detail.historySummary.checks}</strong> controlli registrati</span></div>}
    {page.pendingConfirmation && <div className="notice amber"><Clock3 size={18} /><span>Una differenza osservata il {date(page.pendingConfirmation.firstSeenAt)} è ancora da verificare. Il riferimento precedente resta disponibile. {site.paused ? 'Puoi ripetere il controllo manualmente.' : page.pendingConfirmation.retries >= 2 ? 'Raggiunto il limite dei tentativi ravvicinati; il monitoraggio prosegue alla frequenza del sito.' : 'È previsto un controllo di conferma.'}</span></div>}
    <div className="page-detail-tabs"><div className="tabs"><button className={mode === 'preview' ? 'selected' : ''} aria-pressed={mode === 'preview'} onClick={() => setMode('preview')}><Monitor size={16} /> Versioni <span>{versions.length}</span></button><button className={mode === 'compare' ? 'selected' : ''} aria-pressed={mode === 'compare'} disabled={versions.length < 2} title={versions.length < 2 ? 'Servono almeno due versioni per il confronto' : undefined} onClick={() => setMode('compare')}><History size={16} /> Confronta</button><button className={mode === 'checks' ? 'selected' : ''} aria-pressed={mode === 'checks'} onClick={() => setMode('checks')}><Clock3 size={16} /> Controlli <span>{detail.historySummary?.checks ?? detail.checks.length}</span></button><button className={mode === 'rules' ? 'selected' : ''} aria-pressed={mode === 'rules'} onClick={() => setMode('rules')}><Settings2 size={16} /> Zone da monitorare</button></div><span className="muted">Ultimo controllo: {date(page.lastCheckedAt, true)}</span></div>
    {mode === 'preview' && (selected ? <div className="timeline-layout">
      <TimelineView key={page.id} versions={versions} selectedId={selected.id} selectedAt={activeObservation?.createdAt} referenceVersionId={detail.referenceVersionId || page.referenceVersionId} summary={detail.historySummary} observations={observations} select={select} date={date} bytes={bytes} />
      <section className="panel capture-panel"><div className="capture-toolbar"><div><span className="capture-browser-dots"><i /><i /><i /></span><span title={selected.finalUrl}>{host(selected.finalUrl || page.url)}{urlPath(selected.finalUrl || page.url)}</span></div><div className="tabs capture-view-tabs"><button className={view === 'offline' ? 'selected' : ''} aria-pressed={view === 'offline'} onClick={() => setView('offline')}><Globe2 size={15} /> Pagina offline</button><button className={view === 'screenshot' ? 'selected' : ''} aria-pressed={view === 'screenshot'} onClick={() => setView('screenshot')}><Monitor size={15} /> Screenshot</button></div></div>
        <QualitySummary version={selected} reference={selected.id === (detail.referenceVersionId || page.referenceVersionId)} observation={activeObservation} date={date} />
        {view === 'offline' ? <OfflineView key={`${selected.id}:${activeObservation?.createdAt || ''}`} version={selected} at={activeObservation?.createdAt} date={date} /> : <><div className="capture-meta"><span><Monitor size={15} /> Vista desktop</span><time>{date(selected.capturedAt)}</time><Badge tone={selected.statusCode >= 400 ? 'amber' : 'green'}>{selected.statusCode ? `HTTP ${selected.statusCode}` : 'Acquisita'}</Badge></div><div className="screenshot-view">{imageError || !selected.screenshotUrl ? <Empty icon={<Monitor size={28} />} title="Anteprima non disponibile">Puoi consultare la pagina offline o scaricare la copia HTML.</Empty> : <a href={selected.screenshotUrl} target="_blank" rel="noreferrer" title="Apri lo screenshot completo"><img key={selected.id} src={selected.screenshotUrl} alt={`Screenshot di ${page.title || host(page.url)} acquisito il ${date(selected.capturedAt)}`} onError={() => setImageError(true)} /></a>}</div><div className="capture-footer"><a className="text-button" href={selected.htmlUrl} download><ArrowDownToLine size={15} /> Scarica HTML</a><ShieldCheck size={14} /> Screenshot della pagina archiviata.</div></>}
      </section>
    </div> : <section className="panel"><Empty icon={<History size={31} />} title={detail.checks.some(check => isErrorStatus(check.status)) ? 'La prima acquisizione non è riuscita' : 'Nessuna versione archiviata'} action={<ScanButton siteId={site.id} pageId={page.id} running={detail.jobs.some(job => job.status === 'running')} perform={perform} />}>Quando l’acquisizione sarà completata, qui potrai esplorare la pagina e le sue versioni.</Empty></section>)}
    {mode === 'preview' && selected && <VersionAnnotation key={selected.id} versionId={selected.id} capturedAt={date(selected.capturedAt)} />}
    {mode === 'rules' && <RuleEditor key={page.id} pageId={page.id} versions={versions} initial={{ ignoreRules: page.ignoreRules, importantRules: page.importantRules }} inherited={site.ignoreSelectors} saved={refresh} />}
    {mode === 'compare' && <CompareView versions={versions} selectedId={selected?.id} date={date} />}
    {mode === 'checks' && <section className="panel checks-panel"><div className="panel-heading"><div><h2>Tutte le osservazioni</h2><p>Controlli, anomalie e ritorni a varianti precedenti, nell’ordine in cui sono avvenuti.</p></div></div><ObservationList observations={observations} versions={versions} date={date} select={select} total={detail.historySummary?.checks} /></section>}
    {(mode === 'preview' || mode === 'checks') && <><DiagnosticsPanel diagnostics={detail.diagnostics || []} date={date} bytes={bytes} /><ArchiveReview key={page.id} pageId={page.id} date={date} bytes={bytes} refresh={refresh} /></>}
    <section className="panel notes-panel"><div className="notes-heading"><MessageSquare size={20} /><div><h2>Le tue osservazioni</h2><p>Promesse, offerte, esperimenti: conserva il contesto insieme alla pagina.</p></div></div><textarea aria-label="Annotazioni sulla pagina" rows={3} placeholder="Scrivi cosa hai notato in questa landing…" value={notes} onChange={event => setNotes(event.target.value)} /><div><small>Le modifiche visibili aiutano a formulare ipotesi; non rivelano i risultati di conversione.</small><button className="button secondary compact" disabled={savingNotes || notes === (detail.notes || '')} onClick={async () => { setSavingNotes(true); await perform(() => api(`/api/pages/${page.id}`, { method: 'PATCH', body: JSON.stringify({ notes }) }), 'Annotazioni salvate.'); setSavingNotes(false); }}>{savingNotes ? <LoaderCircle size={15} className="spin" /> : <Check size={15} />} Salva note</button></div></section>
  </>;
}


function Modal({ title, subtitle, close, children }: { title: string; subtitle?: string; close: () => void; children: ReactNode }) {
  const dialog = useRef<HTMLDivElement>(null); const closeRef = useRef(close); closeRef.current = close;
  useEffect(() => { const previous = document.activeElement as HTMLElement; const previousOverflow = document.body.style.overflow; document.body.style.overflow = 'hidden'; const timer = setTimeout(() => dialog.current?.querySelector<HTMLElement>('input,button')?.focus(), 10); const keydown = (event: KeyboardEvent) => { if (event.key === 'Escape') closeRef.current(); if (event.key === 'Tab') { const controls = dialog.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]'); if (!controls?.length) return; const first = controls[0], last = controls[controls.length - 1]; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); } } }; document.addEventListener('keydown', keydown); return () => { clearTimeout(timer); document.body.style.overflow = previousOverflow; document.removeEventListener('keydown', keydown); previous?.focus(); }; }, []);
  return <div className="modal-overlay" onMouseDown={event => { if (event.target === event.currentTarget) close(); }}><div className="modal" ref={dialog} role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="modal-heading"><div><h2 id="modal-title">{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button className="icon-button" onClick={close} aria-label="Chiudi finestra"><X size={21} /></button></div>{children}</div></div>;
}

function SiteModal({ site, close, saved }: { site?: Site; close: () => void; saved: () => Promise<void> }) {
  const [name, setName] = useState(site?.name || ''); const [url, setUrl] = useState(site?.url || ''); const [kind, setKind] = useState(site?.kind || 'competitor'); const [intervalHours, setIntervalHours] = useState(site?.intervalHours || 6); const [maxPages, setMaxPages] = useState(site?.maxPages || 30); const [discoveryIntervalHours, setDiscoveryIntervalHours] = useState(site?.discoveryIntervalHours || 24); const [includePaths, setIncludePaths] = useState((site?.includePaths || []).join('\n')); const [excludePaths, setExcludePaths] = useState((site?.excludePaths || []).join('\n')); const [includeSubdomains, setIncludeSubdomains] = useState(site?.includeSubdomains || false); const [paused, setPaused] = useState(site?.paused || false); const [selectors, setSelectors] = useState((site?.ignoreSelectors || []).join('\n')); const [notes, setNotes] = useState(site?.notes || ''); const [advanced, setAdvanced] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function submit(event: FormEvent) { event.preventDefault(); setBusy(true); setError(''); try { const body = { name: name.trim(), url: url.trim(), kind, intervalHours, discoveryIntervalHours, includePaths: includePaths.split('\n').map(v => v.trim()).filter(Boolean), excludePaths: excludePaths.split('\n').map(v => v.trim()).filter(Boolean), maxPages, includeSubdomains, ignoreSelectors: selectors.split('\n').map(value => value.trim()).filter(Boolean), ...(site ? { paused, notes } : {}) }; await api(site ? `/api/sites/${site.id}` : '/api/sites', { method: site ? 'PATCH' : 'POST', body: JSON.stringify(body) }); await saved(); } catch (error) { setError((error as Error).message); } finally { setBusy(false); } }
  return <Modal title={site ? 'Impostazioni del sito' : 'Aggiungi un sito'} subtitle={site ? 'Decidi come seguire la sua evoluzione.' : 'Un indirizzo oggi, una storia da consultare domani.'} close={() => { if (!busy) close(); }}><form onSubmit={submit}><div className="modal-body"><label>Nome del sito<input required maxLength={120} placeholder="Come vuoi chiamarlo nell’archivio" value={name} onChange={event => setName(event.target.value)} /></label><label>Indirizzo iniziale<input type="url" required disabled={!!site} placeholder="https://…" value={url} onChange={event => setUrl(event.target.value)} /><small>Puoi partire dal dominio o da una landing specifica.</small></label><fieldset className="kind-picker"><legend>Questo sito è</legend><label className={kind === 'own' ? 'selected' : ''}><input type="radio" name="site-kind" checked={kind === 'own'} onChange={() => setKind('own')} /><Globe2 size={18} /><span>Un mio sito</span></label><label className={kind === 'competitor' ? 'selected' : ''}><input type="radio" name="site-kind" checked={kind === 'competitor'} onChange={() => setKind('competitor')} /><Search size={18} /><span>Un competitor</span></label></fieldset><div className="form-columns"><label>Controlla le pagine ogni<div className="input-suffix"><input type="number" required min={1} max={8760} value={intervalHours} onChange={event => setIntervalHours(Number(event.target.value))} /><span>ore</span></div></label><label>Limite di pagine per sito<input type="number" required min={1} max={500} value={maxPages} onChange={event => setMaxPages(Number(event.target.value))} /></label></div><label>Cerca nuove landing ogni<div className="input-suffix"><input type="number" required min={1} max={8760} value={discoveryIntervalHours} onChange={event => setDiscoveryIntervalHours(Number(event.target.value))} /><span>ore</span></div></label><div className="form-info"><Clock3 size={18} /><span>La ricerca di nuovi indirizzi e i controlli delle pagine già note hanno frequenze indipendenti. I lavori vengono eseguiti uno alla volta.</span></div><label className="checkbox-label"><input type="checkbox" checked={includeSubdomains} onChange={event => setIncludeSubdomains(event.target.checked)} /><span>Includi anche i sottodomini<small>Per trovare pagine pubbliche collegate su sottodomini dello stesso sito.</small></span></label>{site && <label className="checkbox-label"><input type="checkbox" checked={paused} onChange={event => setPaused(event.target.checked)} /><span>Metti in pausa il monitoraggio<small>Le copie già archiviate restano consultabili.</small></span></label>}<button type="button" className="advanced-toggle" onClick={() => setAdvanced(!advanced)}><Settings2 size={15} /> Opzioni avanzate <ChevronRight className={advanced ? 'rotate' : ''} size={15} /></button>{advanced && <div className="advanced-fields"><label>Cerca nuove landing in questi percorsi<textarea rows={2} placeholder="/offerte\n/webinar" value={includePaths} onChange={event => setIncludePaths(event.target.value)} /><small>Un percorso per riga. Lascia vuoto per cercare in tutto il sito.</small></label><label>Escludi dalla scoperta questi percorsi<textarea rows={2} placeholder="/privacy\n/blog" value={excludePaths} onChange={event => setExcludePaths(event.target.value)} /><small>Si applica ai nuovi indirizzi. Le pagine già archiviate e gli URL aggiunti a mano continuano a essere controllati.</small></label><label>Elementi da ignorare nei confronti<textarea rows={3} placeholder="Un selettore CSS per riga" value={selectors} onChange={event => setSelectors(event.target.value)} /><small>Per esempio contatori o contenuti variabili. Gli elementi sono esclusi dal confronto; le nuove copie HTML e gli screenshot rimangono completi. Puoi anche scegliere le zone con un clic dal dettaglio di una pagina.</small></label>{site && <label>Note sul sito<textarea rows={3} value={notes} onChange={event => setNotes(event.target.value)} /></label>}</div>}{error && <div className="notice error" role="alert">{error}</div>}</div><div className="modal-footer"><button type="button" className="button secondary" disabled={busy} onClick={close}>Annulla</button><button className="button primary" disabled={busy}>{busy ? <LoaderCircle size={17} className="spin" /> : site ? <Check size={17} /> : <Plus size={17} />}{site ? 'Salva impostazioni' : 'Aggiungi e acquisisci'}</button></div></form></Modal>;
}

function AddPageModal({ site, close, saved }: { site: Site; close: () => void; saved: () => Promise<void> }) {
  const [url, setUrl] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  return <Modal title="Aggiungi una pagina" subtitle={`La nuova pagina sarà associata a ${site.name}.`} close={() => { if (!busy) close(); }}><form onSubmit={async event => { event.preventDefault(); setBusy(true); setError(''); try { await post(`/api/sites/${site.id}/pages`, { url: url.trim() }); await saved(); } catch (error) { setError((error as Error).message); } finally { setBusy(false); } }}><div className="modal-body"><label>Indirizzo della landing<input type="url" required placeholder="https://…" value={url} onChange={event => setUrl(event.target.value)} /><small>Incolla l’indirizzo completo trovato sul sito, in un annuncio o in una newsletter.</small></label>{error && <div className="notice error" role="alert">{error}</div>}</div><div className="modal-footer"><button type="button" className="button secondary" disabled={busy} onClick={close}>Annulla</button><button className="button primary" disabled={busy}>{busy ? <LoaderCircle size={17} className="spin" /> : <Plus size={17} />} Aggiungi pagina</button></div></form></Modal>;
}
